//-----------------------------------------------------------
// Rate Events
//-----------------------------------------------------------

data class CreateRateEvent(
    @Id var rateId: UUID? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "unitPrice_amount")),
      AttributeOverride( name = "currency", column = Column(name = "unitPrice_currency"))
    )
    var unitPrice: Money? = null,
    @Enumerated(EnumType.STRING) var adFormat: AdFormat? = null,
    @Enumerated(EnumType.STRING) var pricingModel: PricingModel? = null
)

data class UpdateRateEvent(
    @Id var rateId: UUID? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "unitPrice_amount")),
      AttributeOverride( name = "currency", column = Column(name = "unitPrice_currency"))
    )
    var unitPrice: Money? = null,
    var rateCard: RateCard? = null,
    var adSlot: AdSlot? = null,
    @Enumerated(EnumType.STRING) var adFormat: AdFormat? = null,
    @Enumerated(EnumType.STRING) var pricingModel: PricingModel? = null
)

data class DeleteRateEvent(@Id val rateId: UUID? = null)

